public class AbstractEmulationEquivalenceTest : AbstractGenericTest {
	protected static readonly TaskMonitor MONITOR = new ConsoleTaskMonitor();

	protected static class TestMemoryFaultHandler : MemoryFaultHandler {
		/* @Override */
		public bool uninitializedRead(Address address, int size, byte[] buf, int bufOffset) {
			return false;
